import 'dart:convert';
import 'package:dmtools/dmtools.dart';

void main() {
  final out = <String, List<String>>{
    for (final t in createDefaultToolRegistry().allTools)
      t.name: t.params.map((p) => p.name).toList(),
  };
  print(const JsonEncoder().convert(out));
}

