arguments.command:
python3 << 'EOF'
import json
java = {t['name']: t for t in json.load(open('/tmp/tools-raw.json'))['tools']}
dart = json.load(open('/tmp/dart_params_full.json'))
exact = set(java) & set(dart)
# after fixing the two in-scope tools, which tools would have name+required parity?
drift_names, drift_req, ok = [], [], []
for n in sorted(exact):
    j = java[n]['inputSchema']
    jp, jreq = sorted(j['properties']), set(j.get('required', []))
    dp, dreq = sorted(dart[n]['params']), set(dart[n]['required'])
    if jp == dp:
        if jreq != dreq: drift_req.append((n, sorted(jreq), sorted(dreq)))
        else: ok.append(n)
    else:
        drift_names.append(n)
print(f"parity_ok={len(ok)} name_drift={len(drift_names)} required_only_drift={len(drift_req)}")
for n, j, d in drift_req: print(f"  req {n}: java={j} dart={d}")
EOF

